import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.Dc-w_e1r.js";const u=JSON.parse('{"title":"Баланс и биллинг","description":"","frontmatter":{},"headers":[],"relativePath":"guide/billing.md","filePath":"guide/billing.md"}'),i={name:"guide/billing.md"};function n(l,e,c,s,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="баланс-и-биллинг" tabindex="-1">Баланс и биллинг <a class="header-anchor" href="#баланс-и-биллинг" aria-label="Permalink to &quot;Баланс и биллинг&quot;">​</a></h1><p>OpenRussiaRouter использует единую систему предоплаченного биллинга в <strong>долларах США (USD)</strong>.</p><h2 id="как-работает-списание" tabindex="-1">Как работает списание <a class="header-anchor" href="#как-работает-списание" aria-label="Permalink to &quot;Как работает списание&quot;">​</a></h2><p>Списание средств происходит автоматически после каждого успешного запроса к модели на основе фактически использованных токенов (Token Usage).</p><p>Формула расчета стоимости запроса:</p><p><code>Стоимость = (InputTokens * InputPrice + OutputTokens * OutputPrice + CacheTokens * CachePrice) / 1,000,000</code></p><h3 id="особенности-учета-токенов" tabindex="-1">Особенности учета токенов <a class="header-anchor" href="#особенности-учета-токенов" aria-label="Permalink to &quot;Особенности учета токенов&quot;">​</a></h3><ul><li><strong>Кэширование:</strong> Если модель поддерживает кэширование (например, Anthropic Prompt Caching), токены, попавшие в кэш, биллятся по специальной (обычно сниженной) цене <code>CachePrice</code>. Эти токены вычитаются из общих <code>InputTokens</code> при расчете стоимости по базовой цене.</li><li><strong>Округление:</strong> Округление происходит до 6 знаков после запятой (микроценты).</li></ul><h2 id="пополнение-баланса" tabindex="-1">Пополнение баланса <a class="header-anchor" href="#пополнение-баланса" aria-label="Permalink to &quot;Пополнение баланса&quot;">​</a></h2><p>Пополнение баланса осуществляется через личный кабинет. Конвертация в USD происходит по актуальному курсу на момент зачисления средств.</p><p>В личном кабинете вы можете выбрать удобную валюту отображения (Display Currency), например, рубли (RUB) или евро (EUR) — пересчет происходит автоматически с использованием актуальных курсов.</p><h2 id="ошибки-при-нулевом-балансе" tabindex="-1">Ошибки при нулевом балансе <a class="header-anchor" href="#ошибки-при-нулевом-балансе" aria-label="Permalink to &quot;Ошибки при нулевом балансе&quot;">​</a></h2><p>Если ваш баланс опустится ниже нуля, API начнет возвращать ошибку <code>insufficient_balance</code> (HTTP 402 / 400).</p>',13)])])}const _=a(i,[["render",n]]);export{u as __pageData,_ as default};
